mapper.select:
SELECT rs.ID, rs.AUDITEENAME, rs.AUDITEENAMEID, rs.IMPLEMENTATIONTIME, rs.PROJECTNAME, rs.RESPONSIBLECONTENT, rs.CONTENTOBJECTIVES, rs.EXECUTEDPROCEDURESPROCESSES, rs.VERIFICATIONSITUATION, rs.CLUESSOURCES, rs.CREATEUSER, rs.CREATETIME, rs.UPDATEUSER, rs.UPDATETIME, rs.DELFLAG, rs.PROJECTID, rs.STATUS, rs.INDEXNO, rs.RESERVED, rs.NO, STA.REALNAME FROM TBL_YQNS_AUDIT_WORK_RECORDS rs LEFT JOIN TBL_STAFF sta on RS.CREATEUSER=to_char(STA.STAFFID)
rs.AUDITEENAMEID = #{auditeeNameId}
and rs.PROJECTNAME like concat(concat('%',#{projectName}),'%')
and rs.PROJECTID = #{projectId}
and rs.INDEXNO like concat(concat('%',#{indexno}),'%')
and rs.STATUS = #{status}
and rs.CREATEUSER = #{createUser}

mapper.update:
